}

@pure
fn digitSum(n: Int) -> Int {
    let total: Int = 0;
    let x: Int = n;
    loop {
        if x == 0 {
            break;
        }
        total = total + x % 10;
        x = x div 10;
    }
    ret total;
}

fn main() -> Void {
    let trains: Int[] = [104, 237, 56, 891, 340, 77, 625, 18];
    loop n in trains {
        let d: Int = digitSum(n);
        let m: Int = n % 17;
        let score: Int = (d * 3 + m) % 29;
        fx {
            println("Train ", n, ": digitsum=", d, " mod17=", m, " score=", score);
        }
    }
    ret;
}

fn main() -> Void {
    let nums: Int[] = [41, 128, 7, 250, 99, 363, 14, 500];
    loop c in nums {
        let r: Int = c % 5;
        let digits: Int[] = [];
        let n: Int = c;
        if n == 0 {
            digits = digits + [0];
        } else {
            loop {
                let d: Int = n % 6;
                digits = digits + [d];
                n = n div 6;
                if n == 0 {
                    break;
                }
            }
        }
        let k: Int = length(digits);
        let line: Text = "Catalog " + int_to_text(c) + ": base6=";
        loop i in 0..k {
            let idx: Int = k - 1 - i;
            if i > 0 {
                line = line + " ";
            }
            line = line + int_to_text(digits[idx]);
        }
        line = line + " mod5=" + int_to_text(r);
        fx {
            println(line);
        }
    }
    ret;
}

