@pure
fn is_upper(ch: Text) -> Bool {
    let c: Int = ord(ch);
    ret c >= 65 && c <= 90;
}

@pure
fn is_digit(ch: Text) -> Bool {
    let c: Int = ord(ch);
    ret c >= 48 && c <= 57;
}

@pure
fn validate(ref: Text) -> Text {
    if string_len(ref) != 8 {
        ret "INVALID";
    }
    loop i in 0..4 {
        if !is_upper(ref[i]) {
            ret "INVALID";
        }
    }
    loop i in 4..8 {
        if !is_digit(ref[i]) {
            ret "INVALID";
        }
    }
    ret "VALID";
}

fn main() -> Void {
    let refs: Text[] = ["AB12XY9012", "CD34UV6789", "EF56WX2345", "GH78YZ7890", "IJ90AB1111", "KL12CD2222"];
    let classes: Text[] = ["Standard", "Premium", "Standard", "Standard", "Premium", "Standard"];
    let valid: Int = 0;
    let invalid: Int = 0;

    loop i in 0..length(refs) {
        let result: Text = validate(refs[i]);
        if result == "VALID" {
            valid = valid + 1;
        } else {
            invalid = invalid + 1;
        }
        fx {
            println(refs[i], " ", result, " ", classes[i]);
        }
    }

    fx {
        println("Valid: ", valid, " Invalid: ", invalid);
    }
    ret;
}

@pure
fn is_valid_dest(d: Text) -> Bool {
    let n: Int = string_len(d);
    if n == 0 {
        ret false;
    }
    let first: Text = d[0];
    if !(is_upper(first)) {
        ret false;
    }
    loop i in 0..n {
        let ch: Text = d[i];
        if !(is_alpha(ch) || is_space(ch)) {
            ret false;
        }
    }
    ret true;
}

@pure
fn is_valid_platform(p: Text) -> Bool {
    if string_len(p) != 2 {
        ret false;
    }
    if p[0] != "P" {
        ret false;
    }
    ret is_digit(p[1]);
}

fn main() -> Void {
    let signs: Text[] = ["York|P3", "leeds|P7", "Manchester|P12", "Birmingham|P5", "Glasgow!|P8", "Edinburgh|P9"];
    let okCount: Int = 0;
    let badDestCount: Int = 0;
    let badPlatCount: Int = 0;
    let bothBadCount: Int = 0;

    loop sign in signs {
        let pipeIdx: Int = index_of(sign, "|");
        let dest: Text = sign[0..pipeIdx];
        let plat: Text = sign[pipeIdx + 1..];
        let destOk: Bool = is_valid_dest(dest);
        let platOk: Bool = is_valid_platform(plat);
        let status: Text = "";
        if destOk && platOk {
            status = "OK";
            okCount = okCount + 1;
        } else if !destOk && platOk {
            status = "BAD DEST";
            badDestCount = badDestCount + 1;
        } else if destOk && !platOk {
            status = "BAD PLATFORM";
            badPlatCount = badPlatCount + 1;
        } else {
            status = "BOTH BAD";
            bothBadCount = bothBadCount + 1;
        }
        fx {
            println(dest, ": ", status);
        }
    }

    fx {
        println("OK: ", okCount, " BAD DEST: ", badDestCount, " BAD PLATFORM: ", badPlatCount, " BOTH BAD: ", bothBadCount);
    }
    ret;
}

fn titleCaseWord(w: Text) -> Text {
    let n: Int = string_len(w);
    if n == 0 {
        ret "";
    }
    let first: Text = w[0];
    let rest: Text = w[1..];
    let firstUpper: Text = upper(first);
    let restLower: Text = lower(rest);
    ret firstUpper + restLower;
}

fn titleCase(s: Text) -> Text {
    let parts: Text[] = split(s, " ");
    let out: Text[] = [];
    loop p in parts {
        out = out + [titleCaseWord(p)];
    }
    ret join(out, " ");
}

fn main() -> Void {
    let titles: Text[] = [
        "blue Monday",
        "HAPPY birthday",
        "wonderwall",
        "Bohemian Rhapsody",
        "99 luftballons",
        "Smells Like teen spirit"
    ];
    let cleaned: Text[] = [];
    loop t in titles {
        cleaned = cleaned + [titleCase(t)];
    }
    let longest: Text = cleaned[0];
    let longestLen: Int = string_len(longest);
    loop i in 1..length(cleaned) {
        let len: Int = string_len(cleaned[i]);
        if len > longestLen {
            longestLen = len;
            longest = cleaned[i];
        }
    }
