@pure
fn isbn_valid(isbn: Text) -> Bool {
    if string_len(isbn) != 10 {
        ret false;
    }
    let total: Int = 0;
    loop i in 0..9 {
        let ch: Text = isbn[i];
        if !is_digit(ch) {
            ret false;
        }
        let d: Int = parse_int(ch);
        total = total + d * (i + 1);
    }
    let last: Text = isbn[9];
    let check: Int;
    if last == "X" {
        check = 10;
    } else if is_digit(last) {
        check = parse_int(last);
    } else {
        ret false;
    }
    total = total + 10 * check;
    ret total % 11 == 0;
}

