fn main() -> Void {
    let dirt: Int[] = [12, 5, 20, 8, 15, 3, 18, 10];
    let path: Int[] = [0, 2, 5, 7, 1, 6, 3, 4];
    let battery: Int = 100;

    loop i in 0..length(path) {
        let cell: Int = path[i];
