fn main() -> Void {
    let arrive: Int[] = [0, 3, 5, 9, 14, 16, 20, 25, 28, 33];
    let serve: Int[] = [12, 8, 15, 6, 10, 4, 9, 7, 11, 5];
    let n: Int = length(arrive);
    let start: Int[] = [];
    let end: Int[] = [];
    let prevEnd: Int = 0;

    loop i in 0..n {
        let s: Int = max(arrive[i], prevEnd);
        let e: Int = s + serve[i];
        start = start + [s];
        end = end + [e];
        prevEnd = e;
        fx {
            println("Student ", i + 1, ": start=", s, ", end=", e);
        }
    }

    let maxWaiting: Int = 0;
    loop i in 0..n {
        // Check at arrival time
        let countAtArrive: Int = 0;
        loop j in 0..n {
            if arrive[j] <= arrive[i] && start[j] > arrive[i] {
                countAtArrive = countAtArrive + 1;
            }
        }
        if countAtArrive > maxWaiting {
            maxWaiting = countAtArrive;
        }
        // Check at start time
        let countAtStart: Int = 0;
        loop j in 0..n {
            if arrive[j] <= start[i] && start[j] > start[i] {
                countAtStart = countAtStart + 1;
            }
        }
        if countAtStart > maxWaiting {
            maxWaiting = countAtStart;
        }
    }

    fx {
        println("Max waiting: ", maxWaiting);
    }
    ret;
}

