fn main() -> Void {
    let calls: Call[] = [];
    calls = calls + [new Call { id: 1, arrive: 0, sev: 2, dur: 12 }];
    calls = calls + [new Call { id: 2, arrive: 3, sev: 1, dur: 20 }];
    calls = calls + [new Call { id: 3, arrive: 5, sev: 3, dur: 8 }];
    calls = calls + [new Call { id: 4, arrive: 8, sev: 2, dur: 15 }];
    calls = calls + [new Call { id: 5, arrive: 14, sev: 1, dur: 18 }];
    calls = calls + [new Call { id: 6, arrive: 18, sev: 3, dur: 6 }];
    calls = calls + [new Call { id: 7, arrive: 22, sev: 2, dur: 10 }];
    calls = calls + [new Call { id: 8, arrive: 25, sev: 1, dur: 14 }];
    calls = calls + [new Call { id: 9, arrive: 30, sev: 3, dur: 9 }];

    let truckFree: Int[] = [0, 0];
    let n: Int = length(calls);

    loop i in 0..n {
        let dispatchTime: Int = truckFree[0];
        let truckIdx: Int = 0;
        if truckFree[1] < truckFree[0] {
            dispatchTime = truckFree[1];
            truckIdx = 1;
        }
        if calls[i].arrive > dispatchTime {
            dispatchTime = calls[i].arrive;
        }
        calls[i].truck = truckIdx + 1;
        calls[i].end = dispatchTime + calls[i].dur;
        truckFree[truckIdx] = calls[i].end;
    }

    fx {
        loop i in 0..n {
            println("Call ", calls[i].id, ": truck=", calls[i].truck, ", end=", calls[i].end);
        }
        let allClear: Int = truckFree[0];
        if truckFree[1] > allClear {
            allClear = truckFree[1];
        }
        println("All clear: ", allClear);
    }
    ret;
}

