fn countChanges(path: Text) -> Int {
    let changes: Int = 0;
    loop i in 1..string_len(path) {
        if path[i] != path[i - 1] {
            changes = changes + 1;
        }
    }
    ret changes;
}

fn allDownsAtLeastRights(path: Text) -> Bool {
    let d: Int = 0;
    let r: Int = 0;
    loop ch in path {
        if ch == "D" {
            d = d + 1;
        } else {
            r = r + 1;
        }
        if d < r {
            ret false;
        }
    }
    ret true;
}

fn main() -> Void {
    let paths: Text[] = ["DDRR", "DRDR", "DRRD", "RDDR", "RDRD", "RRDD"];
    let total: Int = length(paths);
    let evenCount: Int = 0;
    let oddCount: Int = 0;
    let prefixCount: Int = 0;

    loop p in paths {
        let changes: Int = countChanges(p);
        if changes % 2 == 0 {
            evenCount = evenCount + 1;
        } else {
            oddCount = oddCount + 1;
        }
        if allDownsAtLeastRights(p) {
            prefixCount = prefixCount + 1;
        }
    }

    fx {
        println("Total Paths: ", total);
        println("Even Changes: ", evenCount);
