fn main() -> Void {
    let colors: Text[] = ["K", "N", "R"];
    let consecutive: Int = 0;
    let exactlyTwo: Int = 0;
    let palindromes: Int = 0;
    let total: Int = 0;

    loop a in 0..3 {
        loop b in 0..3 {
            loop c in 0..3 {
                loop d in 0..3 {
                    total = total + 1;
                    let s: Text = colors[a] + colors[b] + colors[c] + colors[d];

                    if s[0] == s[1] || s[1] == s[2] || s[2] == s[3] {
                        consecutive = consecutive + 1;
                    }

                    let hasK: Bool = false;
                    let hasN: Bool = false;
                    let hasR: Bool = false;
                    loop ch in s {
                        if ch == "K" {
                            hasK = true;
                        }
                        if ch == "N" {
                            hasN = true;
                        }
                        if ch == "R" {
                            hasR = true;
                        }
                    }
                    let distinct: Int = 0;
                    if hasK {
                        distinct = distinct + 1;
                    }
                    if hasN {
                        distinct = distinct + 1;
                    }
                    if hasR {
                        distinct = distinct + 1;
                    }
                    if distinct == 2 {
                        exactlyTwo = exactlyTwo + 1;
                    }

                    if s[0] == s[3] && s[1] == s[2] {
                        palindromes = palindromes + 1;
                    }
                }
            }
        }
    }

    fx {
        println("Consecutive Match: ", consecutive);
        println("Exactly Two Colors: ", exactlyTwo);
        println("Palindromes: ", palindromes);
        println("Total: ", total);
    }
    ret;
}

