fn main() -> Void {
    let paths: Text[] = [];
    let diagCounts: Int[] = [];

    fn explore(r: Int, c: Int, moves: Text, diag: Int) -> Void {
        if r == 3 && c == 3 {
            let d: Int = diag;
            if r == c {
                d = d + 1;
            }
            paths = paths + [moves];
            diagCounts = diagCounts + [d];
            ret;
        }
        if r > 3 || c > 3 {
            ret;
        }
        if r == 2 && c == 2 {
            ret;
        }
        let newDiag: Int = diag;
        if r == c {
            newDiag = diag + 1;
        }
        if c < 3 {
            explore(r, c + 1, moves + "R", newDiag);
        }
        if r < 3 {
            explore(r + 1, c, moves + "D", newDiag);
        }
        ret;
    }

    explore(1, 1, "", 0);

    let n: Int = length(paths);
    loop i in 0..n {
        loop j in 0..n - 1 - i {
            if paths[j] > paths[j + 1] {
                let tp: Text = paths[j];
                paths[j] = paths[j + 1];
                paths[j + 1] = tp;
                let td: Int = diagCounts[j];
                diagCounts[j] = diagCounts[j + 1];
                diagCounts[j + 1] = td;
            }
        }
    }

    let twoCount: Int = 0;
    loop i in 0..n {
        if diagCounts[i] == 2 {
            twoCount = twoCount + 1;
        }
    }

    fx {
        println("Total Paths: ", n);
        loop i in 0..n {
            println(paths[i]);
        }
        println("Visit Two Diagonal Cells: ", twoCount);
    }
    ret;
}

