fn main() -> Void {
    let evenCount: Int = 0;
    let oneTransCount: Int = 0;
    let symCount: Int = 0;
    let twoOnes: Text[] = [];

    loop n in 0..16 {
        let b1: Int = (n >> 3) & 1;
        let b2: Int = (n >> 2) & 1;
        let b3: Int = (n >> 1) & 1;
        let b4: Int = n & 1;

        let ones: Int = b1 + b2 + b3 + b4;

        if ones % 2 == 0 {
            evenCount = evenCount + 1;
        }

        let trans: Int = 0;
        if b1 != b2 {
            trans = trans + 1;
        }
        if b2 != b3 {
            trans = trans + 1;
        }
        if b3 != b4 {
            trans = trans + 1;
        }
        if trans == 1 {
            oneTransCount = oneTransCount + 1;
        }

        if b1 == b4 && b2 == b3 {
            symCount = symCount + 1;
        }

        if ones == 2 {
            let s: Text = int_to_text(b1) + int_to_text(b2) + int_to_text(b3) + int_to_text(b4);
            twoOnes = twoOnes + [s];
        }
    }

    fx {
        println("Even Ones: ", evenCount);
        println("One Transition: ", oneTransCount);
        println("Symmetric: ", symCount);
        println("Two Ones Count: ", length(twoOnes));
        loop s in twoOnes {
            println(s);
        }
    }
    ret;
}

