fn main() -> Void {
    let items: Text[] = ["Postcard", "Magnet", "T-Shirt", "Postcard", "Magnet", "T-Shirt", "T-Shirt", "Postcard", "Magnet", "T-Shirt", "Postcard", "Magnet", "T-Shirt", "Postcard", "T-Shirt"];
    let counts: Map[Text, Int] = {};
    loop it in items {
        counts[it] = get(counts, it, 0) + 1;
    }
    let names: Text[] = keys(counts);
    let order: Text[] = [];
    loop i in 0..length(names) {
        order = order + [names[i]];
    }
    // simple sort: by count desc, then name asc
    loop i in 0..length(order) {
        loop j in 0..(length(order) - 1 - i) {
            let a: Text = order[j];
            let b: Text = order[j + 1];
            let ca: Int = get(counts, a, 0);
            let cb: Int = get(counts, b, 0);
            let swap: Bool = false;
            if ca < cb {
                swap = true;
            }
            if ca == cb && a > b {
                swap = true;
            }
            if swap {
                order[j] = b;
                order[j + 1] = a;
            }
        }
    }
    fx {
        loop name in order {
            println(name, ": ", get(counts, name, 0));
        }
    }
    ret;
}

