fn main() -> Void {
    let trips: Text[] = ["Downtown", "Riverside", "Airport", "Downtown", "University", "Riverside", "Downtown", "Park", "Airport", "University", "Downtown", "Riverside", "Park", "Airport", "Downtown", "University", "Riverside", "Downtown"];
    let counts: Map[Text, Int] = {};
    loop t in trips {
        counts[t] = get(counts, t, 0) + 1;
    }
    let names: Text[] = keys(counts);
    // sort by count desc, then name asc
    loop i in 0..length(names) {
        loop j in 0..length(names) - 1 - i {
            let a: Text = names[j];
            let b: Text = names[j + 1];
            let ca: Int = get(counts, a, 0);
            let cb: Int = get(counts, b, 0);
            if cb > ca || (cb == ca && b < a) {
                names[j] = b;
                names[j + 1] = a;
            }
        }
    }
    fx {
        loop n in names {
            println(n, ": ", get(counts, n, 0));
        }
    }
    ret;
}

