type Entry {
    color: Text = "";
    count: Int = 0;
}

fn main() -> Void {
    let colors: Text[] = ["RED", "BLUE", "GREEN", "RED", "YELLOW", "BLUE", "RED", "GREEN", "YELLOW", "RED", "BLUE", "GREEN"];
    let counts: Map[Text, Int] = {};
    loop c in colors {
        counts[c] = get(counts, c, 0) + 1;
    }

    let entries: Entry[] = [];
    loop k in counts {
        entries = entries + [new Entry { color: k, count: counts[k] }];
    }

    // sort by count desc, then color asc
    loop i in 0..length(entries) {
        loop j in 0..(length(entries) - i - 1) {
            let swap: Bool = false;
            if entries[j].count < entries[j + 1].count {
                swap = true;
            }
            if entries[j].count == entries[j + 1].count && entries[j].color > entries[j + 1].color {
                swap = true;
            }
            if swap {
                let tmp: Entry = entries[j];
                entries[j] = entries[j + 1];
                entries[j + 1] = tmp;
            }
        }
    }

    fx {
        loop e in entries {
            println(e.color, " x ", e.count);
        }
    }
    ret;
}

