fn main() -> Void {
    let durations: Int[] = [35, 50, 40, 45, 30, 55, 40, 35];
    let nLoads: Int = length(durations);
    let nDryers: Int = 3;

    let dryerTimes: Int[] = [0, 0, 0];
    let dryerCounts: Int[] = [0, 0, 0];
    let starts: Int[] = [0; nLoads];
    let dryerStart: Int[] = [0, 0, 0];

    loop i in 0..nLoads {
        let d: Int = i % nDryers;
        starts[i] = dryerStart[d];
        dryerStart[d] = dryerStart[d] + durations[i];
        dryerTimes[d] = dryerTimes[d] + durations[i];
        dryerCounts[d] = dryerCounts[d] + 1;
    }

    let timeTo160: Int = 0;
    let bps: Int[] = [];
    loop i in 0..nLoads {
        bps = bps + [starts[i]];
        bps = bps + [starts[i] + durations[i]];
    }
    bps = sorted(bps);

    loop bi in 0..length(bps) {
        let t0: Int = bps[bi];
        let total0: Real = 0.0;
        loop i in 0..nLoads {
            let s: Int = starts[i];
            let e: Int = s + durations[i];
            if t0 >= e {
                total0 = total0 + durations[i] * 1.0;
            } else if t0 > s {
                total0 = total0 + (t0 - s) * 1.0;
            }
        }
        if total0 >= 160.0 {
            timeTo160 = t0;
            break;
        }
        if bi + 1 < length(bps) {
            let t1: Int = bps[bi + 1];
            let rate: Real = 0.0;
            loop i in 0..nLoads {
                let s: Int = starts[i];
                let e: Int = s + durations[i];
                if t0 >= s && t0 < e {
                    rate = rate + 1.0;
                }
            }
            if rate > 0.0 {
                let need: Real = 160.0 - total0;
                let tHit: Real = t0 * 1.0 + need / rate;
                if tHit <= t1 * 1.0 {
                    timeTo160 = int(tHit);
                    break;
                }
            }
        }
    }

    let lastDryer: Int = 0;
    loop d in 1..nDryers {
        if dryerTimes[d] > dryerTimes[lastDryer] {
            lastDryer = d;
        }
    }

    fx {
        loop d in 0..nDryers {
            println("Dryer ", d + 1, " done: ", dryerTimes[d]);
        }
        println("TimeTo160: ", timeTo160);
        println("LoadsOnLastDryer: ", dryerCounts[lastDryer]);
    }
    ret;
}

