fn main() -> Void {
    let durations: Int[] = [214, 187, 241, 163, 198, 225, 176];
    let n: Int = length(durations);
    let total: Int = 0;
    let longest: Int = 0;
    let shortest: Int = durations[0];
    let starts: Int[] = [];
    let ends: Int[] = [];
    let prevEnd: Int = 0;

    loop i in 0..n {
        let st: Int = 0;
        if i == 0 {
            st = 0;
        } else {
            st = prevEnd - 4;
        }
        let en: Int = st + durations[i];
        starts = starts + [st];
        ends = ends + [en];
        prevEnd = en;
        total = total + durations[i];
        if durations[i] > longest {
            longest = durations[i];
        }
        if durations[i] < shortest {
            shortest = durations[i];
        }
    }

    let wall: Int = total - 4 * (n - 1);
    let avg: Real = total * 1.0 / n;
    let above: Int = 0;
    loop i in 0..n {
        if durations[i] * 1.0 > avg {
            above = above + 1;
        }
    }

    let target: Int = wall - 100;
    let pos: Int = 0;
    loop i in 0..n {
        if starts[i] == target {
            pos = i + 1;
        }
    }

    fx {
        println("WallClock: ", wall);
        println("Longest: ", longest);
        println("Shortest: ", shortest);
        println("AboveAverage: ", above);
        println("TrackAtTMinus100: ", pos);
    }
    ret;
}

type Day {
    name: Text = "";
    count: Int = 0;
}

fn main() -> Void {
    let days: Day[] = [
        new Day { name: "Monday", count: 5 },
        new Day { name: "Tuesday", count: 3 },
        new Day { name: "Wednesday", count: 5 },
        new Day { name: "Thursday", count: 2 },
        new Day { name: "Friday", count: 3 }
    ];

    // Sort: count descending, then name ascending (stable insertion sort)
    loop i in 1..length(days) {
        let key: Day = days[i];
        let j: Int = i - 1;
        loop j >= 0 {
            let swapNeeded: Bool = false;
            if days[j].count < key.count {
                swapNeeded = true;
            } else if days[j].count == key.count && days[j].name > key.name {
                swapNeeded = true;
            }
            if !swapNeeded {
                break;
            }
            days[j + 1] = days[j];
            j = j - 1;
        }
        days[j + 1] = key;
    }

    fx {
        loop d in days {
            println(d.name, ": ", d.count, " absences");
        }
    }
    ret;
}

