            }
            if b.score == a.score && b.order < a.order {
                swap = true;
            }
            if swap {
                players[j] = b;
                players[j + 1] = a;
            }
        }
    }

    fx {
        loop i in 0..length(players) {
            println(i + 1, ". ", players[i].name, " - ", players[i].score, " pts");
