        if current == "Q" {
            if i % 2 == 0 { next = "M"; } else { next = "L"; }
        } else if current == "M" {
            if i % 2 == 0 { next = "L"; } else { next = "Q"; }
        } else {
            if i % 2 == 0 { next = "Q"; } else { next = "M"; }
        }
        current = next;
    }

    fx {
        println("SLOT 0: ", slot0);
        println("SLOT 3: ", slot3);
        println("SLOT 7: ", slot7);
        println("QUIET SLOTS: ", quietCount);
        println("LOUD SLOTS: ", loudCount);
    }
    ret;
}

fn next_zone(zone: Int, minute: Int) -> Int {
    if zone == 1 {
        if minute % 2 == 0 {
            ret 2;
        }
        ret 3;
    }
    if zone == 2 {
        if minute % 2 == 0 {
            ret 3;
        }
        ret 1;
    }
    if minute % 2 == 0 {
        ret 1;
    }
    ret 2;
}

fn main() -> Void {
    let zones: Int[] = [];
    let current: Int = 1;
    zones = zones + [current];
    loop m in 0..11 {
        current = next_zone(current, m);
        zones = zones + [current];
    }

    let count3: Int = 0;
    loop i in 0..12 {
        if zones[i] == 3 {
            count3 = count3 + 1;
        }
    }

    fx {
        println("MIN 0 ZONE: ", zones[0]);
        println("MIN 3 ZONE: ", zones[3]);
        println("MIN 6 ZONE: ", zones[6]);
        println("MIN 9 ZONE: ", zones[9]);
        println("MIN 11 ZONE: ", zones[11]);
        println("ZONE 3 MINUTES: ", count3);
    }
    ret;
}

