fn next_mode(mode: Text, hour: Int) -> Text {
    let even: Bool = hour % 2 == 0;
    if mode == "D" {
        if even { ret "B"; }
        ret "F";
    }
    if mode == "B" {
        if even { ret "D"; }
        ret "F";
    }
    if even { ret "B"; }
    ret "D";
}

