    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [0, 1, 0],
        [0, 0, 0],
        [1, 0, 0]
    ];
    let r: Int = 1;
    let c: Int = 1;

    let north: Int = 0;
    let i: Int = r - 1;
    loop i >= 0 {
        if grid[i][c] == 1 {
            break;
        }
        north = north + 1;
        i = i - 1;
    }

    let east: Int = 0;
    let j: Int = c + 1;
    loop j < 3 {
        if grid[r][j] == 1 {
            break;
        }
        east = east + 1;
        j = j + 1;
    }

    let south: Int = 0;
    let k: Int = r + 1;
    loop k < 3 {
        if grid[k][c] == 1 {
            break;
        }
        south = south + 1;
        k = k + 1;
    }

    let west: Int = 0;
    let m: Int = c - 1;
    loop m >= 0 {
        if grid[r][m] == 1 {
            break;
        }
        west = west + 1;
        m = m - 1;
    }

    fx {
        println("North beam: ", north);
        println("East beam: ", east);
        println("South beam: ", south);
        println("West beam: ", west);
    }
    ret;
}

