fn main() -> Void {
    let cyan: Int[][] = [[10, 20, 30], [40, 50, 60], [70, 80, 90]];
    let magenta: Int[][] = [[90, 80, 70], [60, 50, 40], [30, 20, 10]];
    let mis: Int[][] = [];
    let maxVal: Int = 0;
    let perfect: Int = 0;
    let total: Int = 0;

    loop r in 0..3 {
        let row: Int[] = [];
        loop c in 0..3 {
            let v: Int = abs(cyan[r][c] - magenta[r][c]);
            row = row + [v];
            if v > maxVal {
                maxVal = v;
            }
            if v == 0 {
                perfect = perfect + 1;
            }
            total = total + v;
        }
        mis = mis + [row];
    }

    fx {
        loop r in 0..3 {
            println("Row ", r, ": ", mis[r][0], " ", mis[r][1], " ", mis[r][2]);
        }
        println("Max misregistration: ", maxVal);
        println("Perfect cells: ", perfect);
        println("Total misregistration: ", total);
    }
    ret;
}

fn main() -> Void {
    let readings: Int[][] = [
        [65, 72, 68],
        [80, 85, 78],
        [55, 60, 58],
        [90, 95, 92]
    ];
    let comfortable: Text[] = [];
    let count: Int = 0;

    loop t in 0..4 {
        let avg: Real = sum(readings[t]) * 1.0 / 3.0;
        let rounded: Text = format_float(round_to(avg, 1), 1);
        fx { println("Tray ", t, " average: ", rounded); }
        if avg >= 60.0 && avg <= 85.0 {
            comfortable = comfortable + [int_to_text(t)];
            count = count + 1;
        }
    }

    let list: Text = "none";
    if count > 0 {
        list = join(comfortable, ", ");
    }
    fx {
        println("Comfortable trays: ", list);
        println("Comfortable count: ", count);
    }
    ret;
}
